      },
      "created": "2026-07-28T22:52:46.654+1000",
      "updated": "2026-07-28T22:52:46.654+1000"
    },
    {
      "id": "13580",
      "body": "Hi User:712020:08a6f120-c836-4f71-92db-c97999401c49 review comments resolved. You can now recheck the confluence page: [https://zimmermannworkboard.atlassian.net/wiki/x/BoCrF](https://zimmermannworkboard.atlassian.net/wiki/x/BoCrF)",
      "author": {
        "display_name": "Jhoan Rose Dela Cruz",
        "name": "Jhoan Rose Dela Cruz",
        "email": "jhoan.rose.dela.cruz@accenture.com",
        "avatar_url": "https://avatar-management--avatars.us-west-2.prod.public.atl-paas.net/712020:26b54c48-03dc-4b75-9a3b-4e924b0a4580/f69f9733-9221-48a9-aada-84ece49d3074/48"
